<!-- admin/gestion-infos.php --> <?php session_start(); include('../database/config.php'); if(!isset($_SESSION['role']) || $_SESSION['role']!='admin'){ header("Location: ../login.html"); exit(); } if(isset($_POST['ajouter'])){ $titre=$_POST['titre']; $contenu=$_POST['contenu']; $stmt=$conn->prepare("INSERT INTO infos_entreprise(titre,contenu) VALUES(?,?)"); $stmt->bind_param("ss",$titre,$contenu); $stmt->execute(); } if(isset($_GET['supprimer'])){ $id=$_GET['supprimer']; $conn->query("DELETE FROM infos_entreprise WHERE id_info=$id"); } $result=$conn->query("SELECT * FROM infos_entreprise"); ?> <!DOCTYPE html> <html lang="fr"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title>Gestion des Informations</title> <link rel="stylesheet" href="../assets/css/dashboard.css"> </head> <body> <header><h2>Gestion des Informations de l'entreprise</h2></header> <section class="dashboard"> <div class="card" style="width:100%;max-width:600px;"> <h3>Ajouter une information</h3> <form method="post"> <input type="text" name="titre" placeholder="Titre" required> <textarea name="contenu" placeholder="Contenu" required></textarea> <button type="submit" name="ajouter">Ajouter</button> </form> </div> <div class="card" style="width:100%;max-width:800px;"> <h3>Liste des informations</h3> <table border="1" width="100%" cellpadding="5"> <tr><th>ID</th><th>Titre</th><th>Contenu</th><th>Action</th></tr> <?php while($row=$result->fetch_assoc()){ ?> <tr> <td><?= $row['id_info'] ?></td> <td><?= $row['titre'] ?></td> <td><?= $row['contenu'] ?></td> <td><a href="?supprimer=<?= $row['id_info'] ?>" onclick="return confirm('Supprimer cette info ?')">Supprimer</a></td> </tr> <?php } ?> </table> </div> </section> </body> </html>